from itertools import permutations

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

def valid(d1, d2):
    # d1, d2: dict rider -> bike
    for r in riders:
        if d1[r] == d2[r]:
            return False
    if d1["R"] == "F" or d2["R"] == "F":
        return False
    if d1["Y"] == "J" or d2["Y"] == "J":
        return False
    if d1["T"] != "H" and d2["T"] != "H":
        return False
    if d2["S"] != d1["Y"]:
        return False
    return True

sols = []
for p1 in permutations(bikes):
    d1 = dict(zip(riders, p1))
    if d1["T"] != "J":
        continue
    for p2 in permutations(bikes):
        d2 = dict(zip(riders, p2))
        if valid(d1, d2):
            sols.append((d1, d2))

print("number of valid scenarios with Theresa J on day 1:", len(sols))

opts = {
    "A": lambda d1, d2: d2["R"] == "G",
    "B": lambda d1, d2: d1["S"] == "H",
    "C": lambda d1, d2: d2["Y"] == "H",
    "D": lambda d1, d2: d1["S"] == "J" or d2["S"] == "J",
    "E": lambda d1, d2: d1["T"] == "G" or d2["T"] == "G",
}

results = {}
for k, f in opts.items():
    wit = [s for s in sols if f(*s)]
    results[k] = len(wit)
    print(k, "possible scenarios:", len(wit))
    if wit:
        print("  example day1:", wit[0][0], "day2:", wit[0][1])

could_be_true = [k for k, v in results.items() if v > 0]
print("Options that could be true:", could_be_true)
